import re, math, collections, statistics

# --------------------------------------------------------------------------
# Helpers from the environment (pre‑defined):
#   entities(doc, scope)
#   recorded_end(doc, scope)
#   observed_events(doc, scope)
# --------------------------------------------------------------------------

# --------------------------------------------------------------------------
# Internal utilities
# --------------------------------------------------------------------------
def _get_motion_records(doc, scope):
    """Return dict: object_id -> list of (frame, x, y, vx, vy, speed)."""
    node = node_by_title(doc, f'{scope}: Motion log')
    if not node:
        return {}
    cols = node['table']['columns']
    idx = {c: cols.index(c) for c in cols}
    rec = collections.defaultdict(list)
    for r in node['table']['rows']:
        frame = float(r[idx['frame']])
        objid = re.match(r'(\d+)', r[idx['object']]).group(1)
        x = float(r[idx['x']]); y = float(r[idx['y']])
        vx = float(r[idx['vx']]); vy = float(r[idx['vy']]); sp = float(r[idx['speed']])
        rec[objid].append((frame, x, y, vx, vy, sp))
    return rec


def _advance_one_step(state, dt, decay):
    """Advance a single body’s state by dt frames with linear speed decay."""
    x, y, vx, vy = state
    coeff = max(0.0, 1.0 + decay * dt)     # decay < 0, coeff < 1
    vx_n, vy_n = vx * coeff, vy * coeff
    dx = (vx + vx_n) * dt / 2.0
    dy = (vy + vy_n) * dt / 2.0
    return (x + dx, y + dy, vx_n, vy_n)


def _interpolate_position(prev, nxt, pct):
    """Linear interpolation of position between two states."""
    if pct <= 0.0:
        return prev[0], prev[1]
    if pct >= 1.0:
        return nxt[0], nxt[1]
    x = prev[0] + (nxt[0] - prev[0]) * pct
    y = prev[1] + (nxt[1] - prev[1]) * pct
    return x, y


def _collision_normal(a_pos, b_pos):
    """Return unit vector from a to b."""
    dx = b_pos[0] - a_pos[0]
    dy = b_pos[1] - a_pos[1]
    dist = math.hypot(dx, dy)
    if dist == 0:
        return (0.0, 0.0)
    return (dx / dist, dy / dist)


def _dot(v, w):
    return v[0] * w[0] + v[1] * w[1]


def _relative_velocity(v1, v2):
    return (v1[0] - v2[0], v1[1] - v2[1])


def _project(v, axis):
    return (v[0] * axis[0] + v[1] * axis[1]) * axis


