# Global model parameters
# --------------------------------------------------------------------------
_DECAY_RATE = None                # per‑frame speed decay, set from data
_COLLIDE_RADIUS = 0.33            # approximate radius of an object (center‑to‑surface)
_COLLIDE_DIST = 2 * _COLLIDE_RADIUS
_DT = 0.5                         # simulation time step (frames)
_E = 1.0                          # coefficient of restitution (elastic)

# --------------------------------------------------------------------------
# Estimate global decay from all scopes
# --------------------------------------------------------------------------
def _estimate_decay(doc):
    rec_all = {}
    for node in doc['nodes']:
        if node['kind'] == 'text' and node['title'].startswith('Video '):
            rec_all.update(_get_motion_records(doc, node['title']))
    dists = []
    for rows in rec_all.values():
        for i in range(1, len(rows)):
            dists.append(rows[i][5] - rows[i-1][5])
    return statistics.mean(dists)           # negative value

# --------------------------------------------------------------------------
# Collision response in 2D (elastic)
# --------------------------------------------------------------------------
def _apply_collision(state_map, id_a, id_b, m_a, m_b):
    """Update velocities of the two colliding bodies."""
    (x_a, y_a, vx_a, vy_a) = state_map[id_a]
    (x_b, y_b, vx_b, vy_b) = state_map[id_b]

    normal = _collision_normal((x_a, y_a), (x_b, y_b))
    if normal == (0.0, 0.0):
        return  # identical positions – ignore

    v_rel = _relative_velocity((vx_a, vy_a), (vx_b, vy_b))
    v_rel_norm = _dot(v_rel, normal)

    if v_rel_norm >= 0:
        return  # moving apart

    # Impulse scalar (elastic collision, e=1)
    impulse = -(1 + _E) * v_rel_norm / (1 / m_a + 1 / m_b)

    # Update velocities
    ax, ay = normal[0] * impulse / m_a, normal[1] * impulse / m_a
    bx, by = -normal[0] * impulse / m_b, -normal[1] * impulse / m_b

    state_map[id_a] = (x_a, y_a, vx_a + ax, vy_a + ay)
    state_map[id_b] = (x_b, y_b, vx_b + bx, vy_b + by)

