    # Mass mapping: metal heavy, rubber light
    mass = {eid: 2.0 if 'metal' in obj['description'] else 1.0
            for eid, obj in zip(entities, [entities[eid] for eid in entities])}

    cur_time = start
    events = []

    while cur_time < horizon:
        next_time = min(cur_time + _DT, horizon)
        dt_step = next_time - cur_time

        # Advance all live states
        new_state = {}
        for eid, (x, y, vx, vy) in state.items():
            if birth_time[eid] <= cur_time:
                new_state[eid] = _advance_one_step((x, y, vx, vy), dt_step, _DECAY_RATE)
            else:
                new_state[eid] = (x, y, vx, vy)

        # Detect collisions
        eids = list(new_state.keys())
        for i in range(len(eids)):
            for j in range(i + 1, len(eids)):
                a, b = eids[i], eids[j]

                # Positions at end of step
                ax1, ay1, _, _ = new_state[a]
                bx1, by1, _, _ = new_state[b]

                # Positions at start of step
                ax0, ay0, _, _ = state[a]
                bx0, by0, _, _ = state[b]

                d0 = math.hypot(ax0 - bx0, ay0 - by0)
                d1 = math.hypot(ax1 - bx1, ay1 - by1)

                if d0 > _COLLIDE_DIST and d1 <= _COLLIDE_DIST:
                    # Interpolate to estimate collision time
                    pct = 0.0
                    if d0 != d1:
                        pct = (d0 - _COLLIDE_DIST) / (d0 - d1)  # 0..1
                    col_time = cur_time + pct * dt_step

                    # Positions at collision instant
                    coll_a = _interpolate_position((ax0, ay0), (ax1, ay1), pct)
                    coll_b = _interpolate_position((bx0, by0), (bx1, by1), pct)

                    # Record event after start
                    if col_time >= start:
                        events.append({
                            "time": col_time,
                            "kind": "collision",
                            "participants": [a, b]
                        })

                    # Apply physics: update velocities in new_state
                    _apply_collision(new_state, a, b,
                                     mass[a], mass[b])

        state = new_state
        cur_time = next_time

    events.sort(key=lambda e: e["time"])
    return events

import math, re
from collections import defaultdict

def _distance(p1, p2):
    return math.hypot(p1[0]-p2[0], p1[1]-p2[1])

def _interpolate_states(states, t):
    if not states:
        return None
    if t <= states[0][0]:
        return states[0][1:]  # x,y,vx,vy
    if t >= states[-1][0]:
        f,x,y,vx,vy = states[-1]
        dt = t-f
        return x+vx*dt, y+vy*dt, vx, vy
    for i in range(len(states)-1):
        f0,x0,y0,vx0,vy0 = states[i]
        f1,x1,y1,vx1,vy1 = states[i+1]
        if f0 <= t <= f1:
            fac = (t-f0)/(f1-f0)
            return (x0+fac*(x1-x0), y0+fac*(y1-y0),
                    vx0+fac*(vx1-vx0), vy0+fac*(vy1-vy0))
    return None

def parse_motion(doc, scope):
    node=node_by_title(doc, f'{scope}: Motion log')
    if node is None: return {}
    cols=node['table']['columns']
    f_idx=cols.index('frame'); o_idx=cols.index('object')
    x_idx=cols.index('x'); y_idx=cols.index('y'); vx_idx=cols.index('vx'); vy_idx=cols.index('vy')
    data=defaultdict(list)
    for row in node['table']['rows']:
        f=float(row[f_idx]); oid=row[o_idx].split()[0]
        x=float(row[x_idx]); y=float(row[y_idx]); vx=float(row[vx_idx]); vy=float(row[vy_idx])
        data[oid].append((f,x,y,vx,vy))
    for k in data: data[k].sort(key=lambda r:r[0])
    return data

# === INSPECTION ===
collision_dists=defaultdict(list)
for node in doc['nodes']:
    if not re.match(r'Video \d+', node['title']): continue
    scope=node['title']
    motion=parse_motion(doc, scope)
    ev_node=node_by_title(doc, f'{scope}: Events')
    if ev_node is None: continue
    for line in ev_node['lines']:
        m=re.match(r'Frame (\d+): Object (\d+).+?collides with Object (\d+)', line)
        if not m: continue
        t=int(m[1]); id1=m[2]; id2=m[3]
        st1=_interpolate_states(motion.get(id1,[]), t)
        st2=_interpolate_states(motion.get(id2,[]), t)
        if st1 and st2:
            d=_distance(st1[:2], st2[:2])
            collision_dists[tuple(sorted((id1,id2)))].append(d)

print("Collision distances per pair (mean):")
for pair, dists in collision_dists.items():
    mean=sum(dists)/len(dists)
    print(f"{pair}: mean={mean:.3f}, std={math.sqrt(sum((x-mean)**2 for x in dists)/len(dists)):.3f}")

